<?php
$jenis=$arg??($_GET['jenis']??'rkam'); $tid=(int)($_GET['tahun']??(Helper::tahunAktif($pdo)['id']??0));
$m=Helper::madrasah($pdo); $th=$pdo->prepare("SELECT * FROM tahun_anggaran WHERE id=?");$th->execute([$tid]);$th=$th->fetch();
$rk=$pdo->prepare("SELECT k.*,b.nama_bidang,(SELECT COALESCE(SUM(jumlah),0) FROM realisasi WHERE rkam_id=k.id) AS jml_real FROM rkam k LEFT JOIN bidang b ON b.id=k.bidang_id WHERE k.tahun_id=? ORDER BY k.id");$rk->execute([$tid]);$rk=$rk->fetchAll();
$perSumber=$pdo->query("SELECT s.id,s.kode,s.nama_sumber_dana,COALESCE((SELECT SUM(rs.jumlah) FROM rkam_sumber_dana rs JOIN rkam k ON k.id=rs.rkam_id WHERE rs.sumber_dana_id=s.id AND k.tahun_id=$tid),0) agg,COALESCE((SELECT SUM(r.jumlah) FROM realisasi r JOIN rkam k ON k.id=r.rkam_id WHERE k.tahun_id=$tid AND r.sumber_dana_id=s.id),0) rea FROM sumber_dana s WHERE s.status='aktif' ORDER BY s.nama_sumber_dana")->fetchAll();
$perBidang=$pdo->query("SELECT b.nama_bidang,COUNT(k.id) jml,COALESCE(SUM(k.total_anggaran),0) agg FROM bidang b LEFT JOIN rkam k ON k.bidang_id=b.id AND k.tahun_id=$tid GROUP BY b.id")->fetchAll();
foreach($perBidang as &$pb){$pb['rea']=$pdo->query("SELECT COALESCE(SUM(r.jumlah),0) FROM realisasi r JOIN rkam k ON k.id=r.rkam_id WHERE k.bidang_id=(SELECT id FROM bidang WHERE nama_bidang=".$pdo->quote($pb['nama_bidang']).") AND k.tahun_id=$tid")->fetchColumn();}
unset($pb);
$perBulan=[];for($mm=1;$mm<=12;$mm++){$s=$pdo->prepare("SELECT COALESCE(SUM(r.jumlah),0) FROM realisasi r JOIN rkam k ON k.id=r.rkam_id WHERE k.tahun_id=? AND MONTH(r.tanggal_transaksi)=?");$s->execute([$tid,$mm]);$perBulan[$mm]=(float)$s->fetchColumn();}
$trans=$pdo->prepare("SELECT r.*,k.nama_kegiatan FROM realisasi r JOIN rkam k ON k.id=r.rkam_id WHERE k.tahun_id=? ORDER BY r.tanggal_transaksi DESC LIMIT 200");$trans->execute([$tid]);$trans=$trans->fetchAll();
$hb=[1=>'Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember']; $tglCetak=date('j').' '.$hb[(int)date('n')].' '.date('Y');
$qrK='Ditandatangani secara elektronik | '.($m['nama_madrasah']??'').' | Kepala Madrasah: '.($m['nama_kepala']??'').' / NIP '.($m['nip_kepala']??'-').' | Laporan '.$jenis.' Tahun '.($th['tahun']??'').' | '.$tglCetak;
$qrB='Ditandatangani secara elektronik | '.($m['nama_madrasah']??'').' | Bendahara: '.($m['nama_bendahara']??'').' / NIP '.($m['nip_bendahara']??'-').' | Laporan '.$jenis.' Tahun '.($th['tahun']??'').' | '.$tglCetak;
$lt=['rkam'=>'RKAM','realisasi'=>'Realisasi','sumber'=>'Per Sumber Dana','bidang'=>'Per Bidang','bulanan'=>'Bulanan','transaksi'=>'Transaksi']; $judulLap=$lt[$jenis]??'RKAM';
?>
