<div class="text-xs"><?=Security::e(trim(($m['alamat']??'').' '.($m['desa']??'').' '.($m['kecamatan']??'').' '.($m['kabupaten']??'')))?> • NSM <?=Security::e($m['nsm']??'-')?> • NPSN <?=Security::e($m['npsn']??'-')?></div></div></div>
