<?php $ta=0;foreach($rk as $r):$ta+=$r['total_anggaran'];?><tr><td class="border border-black p-1"><?=Security::e($r['kode_kegiatan']??'-')?></td><td class="border border-black p-1"><?=Security::e($r['nama_kegiatan'])?></td><td class="border border-black p-1"><?=Security::e($r['nama_bidang']??'-')?></td><td class="border border-black p-1"><?=Security::e($r['penanggung_jawab']??'-')?></td><td class="border border-black p-1 text-center"><?=Security::e($r['status'])?></td><td class="border border-black p-1 text-right"><?=number_format($r['total_anggaran'],0,',','.')?></td></tr><?php endforeach;?>
<tr class="font-bold"><td class="border border-black p-1" colspan="5">TOTAL ANGGARAN</td><td class="border border-black p-1 text-right"><?=number_format($ta,0,',','.')?></td></tr></tbody></table>
