<?php $tA=0;$tR=0;foreach($perSumber as $r):$tA+=$r['agg'];$tR+=$r['rea'];?><tr><td class="border border-black p-1"><?=Security::e($r['nama_sumber_dana'])?> (<?=Security::e($r['kode']??'')?>)</td><td class="border border-black p-1 text-right"><?=number_format($r['agg'],0,',','.')?></td><td class="border border-black p-1 text-right"><?=number_format($r['rea'],0,',','.')?></td><td class="border border-black p-1 text-right"><?=number_format($r['agg']-$r['rea'],0,',','.')?></td></tr><?php endforeach;?>
<tr class="font-bold"><td class="border border-black p-1">TOTAL</td><td class="border border-black p-1 text-right"><?=number_format($tA,0,',','.')?></td><td class="border border-black p-1 text-right"><?=number_format($tR,0,',','.')?></td><td class="border border-black p-1 text-right"><?=number_format($tA-$tR,0,',','.')?></td></tr></tbody></table>
<?php foreach($perSumber as $r): $det=$pdo->prepare("SELECT k.nama_kegiatan,COALESCE((SELECT SUM(rs.jumlah) FROM rkam_sumber_dana rs WHERE rs.rkam_id=k.id AND rs.sumber_dana_id=?),0) agg,COALESCE((SELECT SUM(r2.jumlah) FROM realisasi r2 WHERE r2.rkam_id=k.id AND r2.sumber_dana_id=?),0) rea FROM rkam k WHERE k.tahun_id=? AND (EXISTS(SELECT 1 FROM rkam_sumber_dana rs WHERE rs.rkam_id=k.id AND rs.sumber_dana_id=?) OR EXISTS(SELECT 1 FROM realisasi r3 WHERE r3.rkam_id=k.id AND r3.sumber_dana_id=?)) ORDER BY k.nama_kegiatan"); $det->execute([$r['id'],$r['id'],$tid,$r['id'],$r['id']]); $dd=$det->fetchAll(); if(!$dd)continue; ?>
