<?php else:?>
<table class="w-full border-collapse border border-black"><thead><tr class="bg-gray-100"><th class="border border-black p-1 text-left">Tanggal</th><th class="border border-black p-1 text-left">Kegiatan</th><th class="border border-black p-1 text-left">Uraian</th><th class="border border-black p-1">Jumlah</th></tr></thead><tbody><?php $totT=0;foreach($trans as $r):$totT+=$r['jumlah'];?><tr><td class="border border-black p-1"><?=Security::e($r['tanggal_transaksi'])?></td><td class="border border-black p-1"><?=Security::e($r['nama_kegiatan'])?></td><td class="border border-black p-1"><?=Security::e($r['uraian'])?></td><td class="border border-black p-1 text-right"><?=number_format($r['jumlah'],0,',','.')?></td></tr><?php endforeach;?><tr class="font-bold"><td class="border border-black p-1" colspan="3">TOTAL</td><td class="border border-black p-1 text-right"><?=number_format($totT,0,',','.')?></td></tr></tbody></table>
